<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();$flashes=render_flashes();$currentPage='evidence';$pageTitle='Evidence Library';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];if($uid<=0){http_response_code(403);exit('Invalid Assessor account.');}if(as_has_table($conn,'assessment_evidence')){$s=$conn->prepare("SELECT ae.*,aa.attempt_number,u.first_name,u.last_name,ao.code outcome_code,ao.title outcome_title FROM assessment_evidence ae JOIN assessment_attempts aa ON aa.id=ae.attempt_id JOIN users u ON u.id=aa.participant_id JOIN assessment_outcomes ao ON ao.id=aa.outcome_id WHERE aa.assessor_id=? ORDER BY ae.submitted_at DESC");if($s){$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}}require __DIR__.'/_layout_start.php';?>
<div class="as-page-header"><div><span class="as-page-header__eyebrow">Evidence Review</span><h2>Evidence Library</h2><p>Browse evidence attached to assessment attempts assigned to you.</p></div></div><?php if(!$rows):?><div class="as-card"><div class="as-empty"><div class="as-empty__icon"><i class="fas fa-folder-open"></i></div><strong>No evidence found</strong><span>Evidence linked to assigned attempts will appear here.</span></div></div><?php else:?><div class="as-evidence-grid"><?php foreach($rows as $x):$name=trim((string)$x['first_name'].' '.(string)$x['last_name']);?><article class="as-evidence-card"><div class="as-evidence-card__top"><span class="as-evidence-card__icon"><i class="fas fa-file-lines"></i></span><span class="as-chip"><?= e(as_label($x['evidence_type'])) ?></span></div><h3><?= e($x['title']) ?></h3><p><?= e(trim((string)$x['description'])?:'No description provided.') ?></p><div class="as-evidence-card__meta"><span><i class="fas fa-user"></i> <?= e($name) ?></span><span><i class="fas fa-award"></i> <?= e($x['outcome_code']) ?></span><span><i class="fas fa-rotate"></i> Attempt #<?= (int)$x['attempt_number'] ?></span></div><div class="as-evidence-card__footer"><span><?= e(as_datetime($x['submitted_at'])) ?></span><?php if($x['file_path']):?><a class="as-btn as-btn--secondary as-btn--small" href="<?= url($x['file_path']) ?>" target="_blank" rel="noopener">Open <i class="fas fa-arrow-up-right-from-square"></i></a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?><?php require __DIR__.'/_layout_end.php';?>
